    </div><form id="articleForm" class="border-top pt-4 d-grid gap-3" method="post" action="<?= url('admin/saveArticle') ?>"><h3 class="h5" id="articleFormHeading">Novo artigo</h3><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id" id="articleId"><label>Categoria<select class="form-select" name="category" id="articleCategory" required><?php foreach($categories as $c): ?><option value="<?= (int)$c['id_categoria'] ?>"><?= e($c['nome']) ?></option><?php endforeach; ?></select></label><label>Título<input class="form-control" name="title" id="articleTitle" maxlength="200" required></label><label>Resumo<textarea class="form-control" name="summary" id="articleSummary" maxlength="300" rows="2" required></textarea></label><label>Texto do artigo<textarea class="form-control" name="body" id="articleBody" rows="6" required></textarea><small class="form-text">Separe os parágrafos com uma linha em branco.</small></label><label class="form-check"><input class="form-check-input" type="checkbox" name="published" id="articlePublished" checked> Publicar agora</label><button class="btn btn-raizes" type="submit">Salvar artigo</button></form></section></div>
    <div class="col-lg-5"><section class="forum-card p-4"><h2 class="h4">Notícias</h2><div class="d-grid gap-2 mb-4">
      <?php foreach($news as $n): ?><div class="border rounded p-3"><strong><?= e($n['titulo']) ?></strong><div class="small text-soft mb-2"><?= $n['publicado']?'Publicado':'Rascunho' ?><?= $n['destaque']?' · Destaque':'' ?></div><div class="d-flex gap-2"><button class="btn btn-sm btn-raizes-outline" type="button" data-edit-news='<?= e(json_encode(['id'=>$n['id_noticia'],'title'=>$n['titulo'],'summary'=>$n['resumo'],'label'=>$n['rotulo'],'link'=>$n['link'],'published'=>$n['publicado'],'featured'=>$n['destaque']],JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG|JSON_HEX_AMP)) ?>'>Editar</button><form method="post" action="<?= url('admin/deleteNews/'.(int)$n['id_noticia']) ?>"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><button class="btn btn-sm btn-outline-danger">Excluir</button></form></div></div><?php endforeach; ?>
    </div><form id="newsForm" class="border-top pt-4 d-grid gap-3" method="post" action="<?= url('admin/saveNews') ?>"><h3 class="h5" id="newsFormHeading">Nova notícia</h3><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id" id="newsId"><label>Rótulo<input class="form-control" name="label" id="newsLabel" maxlength="40" value="Notícia" required></label><label>Título<input class="form-control" name="title" id="newsTitle" maxlength="200" required></label><label>Resumo<textarea class="form-control" name="summary" id="newsSummary" maxlength="300" rows="2" required></textarea></label><label>Link (opcional)<input class="form-control" type="url" name="link" id="newsLink"></label><label class="form-check"><input class="form-check-input" type="checkbox" name="published" id="newsPublished" checked> Publicar agora</label><label class="form-check"><input class="form-check-input" type="checkbox" name="featured" id="newsFeatured"> Destacar na capa</label><button class="btn btn-raizes" type="submit">Salvar notícia</button></form></section></div>
  </div>
  <section class="forum-card p-4 mt-4"><h2 class="h4">Questionário interativo</h2><div class="row g-3 mb-4"><?php foreach($quizzes as $q): ?><div class="col-md-6"><div class="border rounded p-3 h-100"><strong><?= e($q['pergunta']) ?></strong><div class="small text-soft mt-1"><?= $q['publicado']?'Publicado':'Rascunho' ?></div><div class="d-flex gap-2 mt-2"><button class="btn btn-sm btn-raizes-outline" data-edit-quiz='<?= e(json_encode(['id'=>$q['id_quiz'],'question'=>$q['pergunta'],'a'=>$q['opcao_a'],'b'=>$q['opcao_b'],'c'=>$q['opcao_c'],'d'=>$q['opcao_d'],'correct'=>$q['correta'],'published'=>$q['publicado']],JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG|JSON_HEX_AMP)) ?>'>Editar</button><form method="post" action="<?= url('admin/deleteQuiz/'.(int)$q['id_quiz']) ?>"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><button class="btn btn-sm btn-outline-danger">Excluir</button></form></div></div></div><?php endforeach; ?></div>
    <form id="quizForm" class="border-top pt-4 row g-3" method="post" action="<?= url('admin/saveQuiz') ?>"><h3 class="h5" id="quizFormHeading">Nova pergunta</h3><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id" id="quizId"><label class="col-12">Pergunta<input class="form-control" name="question" id="quizQuestion" maxlength="500" required></label><?php foreach(['a'=>'A','b'=>'B','c'=>'C','d'=>'D'] as $key=>$label): ?><label class="col-md-6">Opção <?= $label ?><input class="form-control" name="<?= $key ?>" id="quiz<?= strtoupper($key) ?>" maxlength="300" required></label><?php endforeach; ?><label class="col-md-6">Resposta correta<select class="form-select" name="correct" id="quizCorrect"><option value="0">A</option><option value="1">B</option><option value="2">C</option><option value="3">D</option></select></label><label class="form-check col-md-6"><input class="form-check-input" type="checkbox" name="published" id="quizPublished" checked> Publicar pergunta</label><div class="col-12"><button class="btn btn-raizes" type="submit">Salvar pergunta</button></div></form>
  </section>
</main>
<script>
document.querySelectorAll('[data-edit-article]').forEach(b=>b.addEventListener('click',()=>{const x=JSON.parse(b.dataset.editArticle);document.querySelector('#articleId').value=x.id;document.querySelector('#articleCategory').value=x.category;document.querySelector('#articleTitle').value=x.title;document.querySelector('#articleSummary').value=x.summary;document.querySelector('#articleBody').value=x.body;document.querySelector('#articlePublished').checked=!!Number(x.published);document.querySelector('#articleFormHeading').textContent='Editar artigo';document.querySelector('#articleForm').scrollIntoView({behavior:'smooth'});}));
document.querySelectorAll('[data-edit-news]').forEach(b=>b.addEventListener('click',()=>{const x=JSON.parse(b.dataset.editNews);document.querySelector('#newsId').value=x.id;document.querySelector('#newsTitle').value=x.title;document.querySelector('#newsSummary').value=x.summary;document.querySelector('#newsLabel').value=x.label;document.querySelector('#newsLink').value=x.link||'';document.querySelector('#newsPublished').checked=!!Number(x.published);document.querySelector('#newsFeatured').checked=!!Number(x.featured);document.querySelector('#newsFormHeading').textContent='Editar notícia';document.querySelector('#newsForm').scrollIntoView({behavior:'smooth'});}));
document.querySelectorAll('[data-edit-quiz]').forEach(b=>b.addEventListener('click',()=>{const x=JSON.parse(b.dataset.editQuiz);document.querySelector('#quizId').value=x.id;document.querySelector('#quizQuestion').value=x.question;['a','b','c','d'].forEach(k=>document.querySelector('#quiz'+k.toUpperCase()).value=x[k]);document.querySelector('#quizCorrect').value=x.correct;document.querySelector('#quizPublished').checked=!!Number(x.published);document.querySelector('#quizFormHeading').textContent='Editar pergunta';document.querySelector('#quizForm').scrollIntoView({behavior:'smooth'});}));
</script>
